#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t a = 0b1100;
    uint32_t b = 0b0011;
    uint32_t r = (a ^ b) & (a ^ b);
    printf("%u\n", r ^ r);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t w = 0xABC;
    uint32_t field = (w >> 4) & 0xFu;
    printf("%u\n", field);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t r = 0;
    r |= (1u << 3);
    r |= (1u << 1);
    r &= ~(1u << 3);
    printf("%u\n", r);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t x = 1u;
    x = x << 31;
    printf("%u\n", x);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t n = 0b10101110;
    unsigned int c = 0;
    while (n) {
        n &= n - 1;
        c++;
    }
    printf("%u\n", c);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t n = 33;
    uint32_t p = 1;
    while (p < n) {
        p <<= 1;
    }
    printf("%u\n", p);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t r = 12;
    uint32_t low = r & (~r + 1u);
    printf("%u\n", low);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint32_t a = 7, b = 5;
    uint64_t result = 0;
    uint64_t x = a, y = b;
    while (y) {
        if (y & 1u) result += x;
        x <<= 1;
        y >>= 1;
    }
    printf("%llu\n", (unsigned long long)result);
    return 0;
}
